require_once __DIR__.'/db.php'; require_once __DIR__.'/../includes/auth.php'; requireAdmin(); header('Content-Type: application/json; charset=UTF-8');
$students=(int)$conn->query('SELECT COUNT(*) n FROM students')->fetch_assoc()['n'];$programs=(int)$conn->query("SELECT COUNT(*) n FROM programs WHERE status='active'")->fetch_assoc()['n'];$volunteers=(int)$conn->query('SELECT COUNT(*) n FROM volunteers')->fetch_assoc()['n'];$trainers=(int)$conn->query('SELECT COUNT(*) n FROM trainers')->fetch_assoc()['n'];$today=date('Y-m-d');$present=(int)$conn->query("SELECT COUNT(*) n FROM attendance WHERE attendance_date='$today' AND status='present'")->fetch_assoc()['n'];$attendanceTotal=(int)$conn->query("SELECT COUNT(*) n FROM attendance WHERE attendance_date='$today'")->fetch_assoc()['n'];$rate=$attendanceTotal?round($present/$attendanceTotal*100):0;$recent=[];$r=$conn->query('SELECT activity,program,username,status,created_at FROM activity_logs ORDER BY id DESC LIMIT 8');while($x=$r->fetch_assoc())$recent[]=$x;echo json_encode(['success'=>true,'students'=>$students,'programs'=>$programs,'volunteers'=>$volunteers,'trainers'=>$trainers,'present'=>$present,'attendance_rate'=>$rate,'recent'=>$recent],JSON_UNESCAPED_UNICODE);?>